\mathsf{Ctx}_{\mathsf M}
=
\bigcup_{n\in\mathbb N}
\left\{
\langle x_i:A_i\rangle_{i<n}:
\forall i<n\ (x_i\in\mathsf{Var}_{\mathsf M}\land A_i\in\mathsf{ValTy}_{\mathsf M})
\land\forall i<j<n\ x_i\ne x_j
\right\}.

\operatorname{Sub}_{\mathsf M}:
(\mathsf{Val}_{\mathsf M}\cup\mathsf{Comp}_{\mathsf M})\times\mathsf{Var}_{\mathsf M}\times\mathsf{Val}_{\mathsf M}
\to
\mathsf{Val}_{\mathsf M}\cup\mathsf{Comp}_{\mathsf M}

\begin{aligned}
\mathsf{MonadEqCert}_{\mathsf M}(c,d)
=\{((c_i)_{i\le n},(q_i)_{i<n}):
&c_0=c,\ c_n=d,\\
&\forall i<n\ q_i\in\mathsf{EqStepCert}_{\mathsf M}(c_i,c_{i+1})\}.
\end{aligned}

\mathsf{Jud}_{\mathsf M}
=
\{\operatorname{vjud}(\Gamma,v,A):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\
v\in\mathsf{Val}_{\mathsf M},A\in\mathsf{ValTy}_{\mathsf M}\}
\cup
\{\operatorname{cjud}(\Gamma,c,C):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\
c\in\mathsf{Comp}_{\mathsf M},C\in\mathsf{CompTy}_{\mathsf M}\}
\cup
\{\operatorname{eqjud}(c,d):c\equiv_{\mathsf M}d\}
\cup
\{\operatorname{redjud}(e,e'):e,e'\in\mathsf{Val}_{\mathsf M}\cup\mathsf{Comp}_{\mathsf M},\ e\to_{\mathsf M}e'\}.

\mathsf{MainJud}_{\mathsf M}
=
\{\operatorname{vjud}(\Gamma,v,A):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\
v\in\mathsf{Val}_{\mathsf M},A\in\mathsf{ValTy}_{\mathsf M}\}
\cup
\{\operatorname{cjud}(\Gamma,c,C):
\Gamma\in\mathsf{Ctx}_{\mathsf M},\
c\in\mathsf{Comp}_{\mathsf M},C\in\mathsf{CompTy}_{\mathsf M}\}
\cup
\{\operatorname{eqjud}(c,d):c,d\in\mathsf{Comp}_{\mathsf M}\}
\cup
\{\operatorname{redjud}(e,e'):e,e'\in\mathsf{Val}_{\mathsf M}\cup\mathsf{Comp}_{\mathsf M}\}.
